<script lang="ts">
	import { invalidateAll } from '$app/navigation';
	import Dropdown, { type DropdownOption } from '$lib/components/ui/Dropdown.svelte';
	type UserRow = { id: string; username: string; displayName: string; email: string; role: string; isOwner: boolean; isBanned: boolean; banUntil: Date | string | null; isShadowBanned: boolean; isVerified: boolean; createdAt: Date | string; karma: number; postKarma: number; commentKarma: number };
	type PostRow = { id: string; title: string; score: number; commentCount: number; createdAt: Date | string; isRemoved: boolean; isStickied: boolean; isLocked: boolean; authorId: string | null; author: string; community: string };
	type ReportRow = { id: string; targetType: string; targetId: string; reason: string; details: string | null; status: string; createdAt: Date | string; reporter: string; postTitle: string | null };
	type CommunityRow = { id: string; name: string; slug: string; memberCount: number; isFeatured: boolean; isPrivate: boolean; category: string };
	type LogRow = { id: string; action: string; targetType: string; targetId: string; reason: string | null; createdAt: Date | string; actor: string };
	type SiteSettings = { siteName: string; tagline: string | null; allowRegistration: boolean; inviteOnly: boolean; enableNsfw: boolean; enableRealtimeFeed: boolean; defaultSort: string; postRateLimitPerHour: number } | null;
	type VerificationRequest = { id: string; userId: string; reason: string; evidenceUrl: string | null; createdAt: Date | string; username: string; displayName: string };
	const { data } = $props() as { data: { viewer: { id: string; name: string; username: string }; stats: { users: number; posts: number; comments: number; communities: number; openReports: number }; users: UserRow[]; posts: PostRow[]; reports: ReportRow[]; communities: CommunityRow[]; logs: LogRow[]; settings: SiteSettings; supportTickets: Array<{ id: string; category: string; subject: string; message: string; status: string; createdAt: Date | string; username: string; email: string | null }>; privacyRequests: Array<{ id: string; requestType: string; details: string | null; status: string; createdAt: Date | string; username: string }>; verificationRequests: VerificationRequest[] } };
	let activeSection = $state('overview');
	let busy = $state(false);
	let notice = $state('');
	let allowRegistration = $state(data.settings?.allowRegistration ?? true);
	let inviteOnly = $state(data.settings?.inviteOnly ?? false);
	let enableNsfw = $state(data.settings?.enableNsfw ?? false);
	let enableRealtimeFeed = $state(data.settings?.enableRealtimeFeed ?? true);
	let defaultSort = $state(data.settings?.defaultSort ?? 'for-you');
	let postRateLimitPerHour = $state(data.settings?.postRateLimitPerHour ?? 10);
	let tagline = $state(data.settings?.tagline ?? '');
	const roleOptions: DropdownOption[] = [{value:'member',label:'Member'},{value:'moderator',label:'Moderator'},{value:'admin',label:'Admin'}];
	const adminSortOptions: DropdownOption[] = [{value:'for-you',label:'For you (personalized)'},{value:'hot',label:'Hot'},{value:'best',label:'Best'},{value:'new',label:'Latest'},{value:'rising',label:'Rising'},{value:'top',label:'Top'}];
	const sections = [
		{ id: 'overview', label: 'Overview', icon: '◈' },
		{ id: 'reports', label: 'Moderation queue', icon: '⚑' },
		{ id: 'posts', label: 'Content', icon: '▤' },
		{ id: 'users', label: 'Members & roles', icon: '◎' },
		{ id: 'verification', label: 'Verification requests', icon: '✓' },
		{ id: 'support', label: 'Customer support', icon: '✉' },
		{ id: 'privacy', label: 'Privacy requests', icon: '⌑' },
		{ id: 'communities', label: 'Communities', icon: '⊞' },
		{ id: 'settings', label: 'Site settings', icon: '⚙' },
		{ id: 'logs', label: 'Audit log', icon: '↻' }
	];
	function niceDate(value: Date | string) { return new Date(value).toLocaleString(undefined, { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }); }
	function compact(value: number) { return new Intl.NumberFormat('en', { notation: 'compact', maximumFractionDigits: 1 }).format(value ?? 0); }
	async function action(payload: Record<string, unknown>, success: string) {
		if (busy) return;
		busy = true; notice = '';
		try {
			const response = await fetch('/api/admin', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
			const result = await response.json(); if (!response.ok) throw new Error(result.error || 'Action failed.');
			notice = success; await invalidateAll();
		} catch (error) { notice = error instanceof Error ? error.message : 'Action failed.'; }
		finally { busy = false; }
	}
	async function banUser(user: UserRow) {
		if (user.isOwner) return;
		const reason = user.isBanned ? '' : (window.prompt(`Reason for permanent suspension of @${user.username}?`, 'Violation of community guidelines') || '');
		if (!user.isBanned && !reason.trim()) return;
		await action({ action: user.isBanned ? 'unbanUser' : 'banUser', targetId: user.id, reason }, user.isBanned ? 'Account restored.' : 'Account permanently suspended.');
	}
	async function tempBanUser(user: UserRow) {
		if (user.isOwner) return;
		const hours = Number(window.prompt(`Temporary ban duration for @${user.username} in hours (1–8760):`, '24'));
		if (!Number.isFinite(hours) || hours < 1 || hours > 8760) return;
		const reason = window.prompt(`Reason for temporary ban of @${user.username}?`, 'Repeated community guideline violations') || '';
		if (!reason.trim()) return;
		await action({ action: 'tempBanUser', targetId: user.id, durationHours: hours, reason }, `Temporary ban applied for ${hours} hour(s).`);
	}
	async function toggleShadowBan(user: UserRow) {
		if (user.isOwner) return;
		const actionName = user.isShadowBanned ? 'unshadowBanUser' : 'shadowBanUser';
		const reason = user.isShadowBanned ? '' : (window.prompt(`Internal reason for shadow ban of @${user.username}?`, 'Coordinated spam or abuse') || '');
		if (!user.isShadowBanned && !reason.trim()) return;
		await action({ action: actionName, targetId: user.id, reason }, user.isShadowBanned ? 'Shadow ban lifted.' : 'Shadow ban applied.');
	}
	async function changeRole(userId: string, role: string) { await action({ action: 'setRole', targetId: userId, role }, 'Member role updated.'); }
	async function saveSettings() {
		await action({ action: 'updateSettings', allowRegistration, inviteOnly, enableNsfw, enableRealtimeFeed, defaultSort, postRateLimitPerHour: Number(postRateLimitPerHour), tagline }, 'Site settings saved.');
	}
</script>

<div class="admin-layout mx-auto grid max-w-[1440px] grid-cols-1 gap-5 px-4 pb-14 sm:px-6 lg:grid-cols-[240px_minmax(0,1fr)] lg:gap-7 lg:px-8">
	<aside class="owner-sidebar surface-card rounded-[1.4rem] p-4">
		<div class="flex items-center gap-3 border-b border-white/[0.06] px-2 pb-5 pt-2"><span class="owner-mark">⌘</span><div><p class="text-sm font-extrabold text-white">Owner studio</p><p class="mt-1 text-[10px] text-slate-600">{data.viewer.username}</p></div></div>
		<p class="px-3 pb-2 pt-5 text-[9px] font-extrabold uppercase tracking-[.17em] text-slate-600">MANAGEMENT</p>
		<nav class="grid gap-1" aria-label="Owner dashboard sections">
			{#each sections as section}<button onclick={() => activeSection = section.id} class={`owner-nav ${activeSection === section.id ? 'owner-nav-active' : ''}`}><span class="owner-nav-icon">{section.icon}</span><span>{section.label}</span>{#if section.id === 'reports' && data.stats.openReports > 0}<span class="owner-badge">{data.stats.openReports}</span>{/if}{#if section.id === 'verification' && data.verificationRequests.length > 0}<span class="owner-badge">{data.verificationRequests.length}</span>{/if}</button>{/each}
		</nav>
		<div class="mt-7 rounded-xl border border-violet-300/10 bg-violet-300/[0.035] p-3.5"><p class="text-xs font-extrabold text-violet-100">Owner-only controls</p><p class="mt-1.5 text-[10px] leading-5 text-slate-500">Moderation actions are recorded in the audit log. Keep reasons clear so future admins can understand decisions.</p></div>
		<a href="/" class="mt-4 flex items-center gap-2 rounded-xl px-3 py-2.5 text-xs font-semibold text-slate-500 transition hover:bg-white/[0.035] hover:text-white">← Return to site</a>
	</aside>

	<section class="min-w-0">
		<div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-[10px] font-extrabold uppercase tracking-[.18em] text-violet-200">NEXUS / ADMINISTRATION</p><h1 class="mt-2 text-3xl font-extrabold tracking-[-.045em] text-white">{sections.find((item) => item.id === activeSection)?.label ?? 'Overview'}</h1><p class="mt-2 text-sm text-slate-500">Community health, safety tools, and site controls in one place.</p></div><span class="owner-status"><span class="h-1.5 w-1.5 rounded-full bg-emerald-300"></span> Owner access verified</span></div>
		{#if notice}<div class="mt-4 rounded-xl border border-indigo-300/10 bg-indigo-300/[0.04] px-4 py-3 text-xs text-indigo-100" role="status">{notice}</div>{/if}

		{#if activeSection === 'overview'}
			<div class="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
				{#each [{label:'Members',value:data.stats.users,icon:'◎',hint:'registered accounts'},{label:'Posts',value:data.stats.posts,icon:'▤',hint:'all published content'},{label:'Replies',value:data.stats.comments,icon:'↳',hint:'thread activity'},{label:'Communities',value:data.stats.communities,icon:'⊞',hint:'active spaces'},{label:'Reports',value:data.stats.openReports,icon:'⚑',hint:'awaiting review'}] as stat}
					<div class={`stat-card surface-card rounded-2xl p-4 ${stat.label === 'Reports' && stat.value > 0 ? 'stat-alert' : ''}`}><div class="flex items-center justify-between"><span class="text-[10px] font-bold uppercase tracking-[.12em] text-slate-500">{stat.label}</span><span class="text-base text-indigo-200">{stat.icon}</span></div><p class="mt-3 text-3xl font-extrabold tracking-tight text-white">{compact(stat.value)}</p><p class="mt-1 text-[10px] text-slate-600">{stat.hint}</p></div>
				{/each}
			</div>
			<div class="mt-5 grid items-start gap-4 xl:grid-cols-[minmax(0,1.1fr)_minmax(0,.9fr)]">
				<section class="surface-card rounded-[1.35rem] p-4 sm:p-5"><div class="flex items-start justify-between gap-3"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">NEEDS ATTENTION</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Latest reports</h2></div><button onclick={() => activeSection = 'reports'} class="text-xs font-bold text-indigo-200 hover:text-white">Open queue ↗</button></div><div class="mt-3 space-y-2.5">{#each data.reports.slice(0, 4) as report}<div class="rounded-xl border border-white/[0.05] bg-white/[0.015] p-3"><div class="flex flex-wrap items-center justify-between gap-2"><span class="rounded-md bg-rose-300/[0.08] px-2 py-1 text-[9px] font-bold uppercase text-rose-100">{report.reason}</span><span class="text-[10px] text-slate-600">by @{report.reporter}</span></div><p class="mt-2 line-clamp-2 text-xs font-semibold text-slate-200">{report.postTitle || `${report.targetType} · ${report.targetId.slice(0, 12)}`}</p><div class="mt-3 flex gap-2"><button onclick={() => action({ action: 'takeDownReport', targetId: report.id, reason: `Reported for ${report.reason}` }, 'Reported content removed and report resolved.')} class="mini-danger">Take down</button><button onclick={() => action({ action: 'dismissReport', targetId: report.id }, 'Report dismissed.')} class="mini-button">Dismiss</button></div></div>{:else}<p class="rounded-xl border border-white/[0.05] p-5 text-center text-xs text-slate-600">No open reports. Nice work.</p>{/each}</div></section>
				<section class="surface-card rounded-[1.35rem] p-4 sm:p-5"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">COMMUNITY MOMENTUM</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Largest communities</h2></div><div class="mt-3 space-y-3">{#each data.communities.slice(0, 5) as community, index}<div class="flex items-center gap-3"><span class="rank-n">{String(index + 1).padStart(2, '0')}</span><div class="min-w-0 flex-1"><p class="truncate text-xs font-bold text-slate-200">c/{community.slug}</p><p class="mt-1 text-[10px] text-slate-600">{compact(community.memberCount)} members · {community.category}</p></div><button onclick={() => action({ action: 'featureCommunity', targetId: community.id }, community.isFeatured ? 'Community removed from featured.' : 'Community featured.')} class={`mini-button ${community.isFeatured ? 'mini-active' : ''}`}>{community.isFeatured ? '★ Featured' : '☆ Feature'}</button></div>{:else}<p class="text-xs text-slate-600">No communities yet.</p>{/each}</div></section>
			</div>
			<section class="surface-card mt-4 rounded-[1.35rem] p-4 sm:p-5"><div class="flex items-center justify-between gap-3"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">LATEST SIGNUPS</p><h2 class="mt-1.5 text-lg font-extrabold text-white">New members</h2></div><button onclick={() => activeSection = 'users'} class="text-xs font-bold text-indigo-200">Manage members ↗</button></div><div class="mt-3 overflow-x-auto"><table class="admin-table"><thead><tr><th>Member</th><th>Role</th><th>Joined</th><th>Status</th></tr></thead><tbody>{#each data.users.slice(0, 6) as user}<tr><td><div class="text-xs font-bold text-slate-200">{user.displayName}</div><div class="mt-1 text-[10px] text-slate-600">@{user.username}</div></td><td><span class="role-pill">{user.role}</span></td><td>{niceDate(user.createdAt)}</td><td><span class={user.isBanned ? 'state-banned' : 'state-active'}>{user.isBanned ? 'Suspended' : 'Active'}</span></td></tr>{/each}</tbody></table></div></section>

		{:else if activeSection === 'reports'}
			<section class="surface-card mt-5 rounded-[1.35rem] p-4 sm:p-5"><div class="flex items-center justify-between gap-3"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">TRUST & SAFETY</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Open moderation queue</h2></div><span class="rounded-full bg-rose-300/[0.08] px-3 py-1.5 text-[10px] font-bold text-rose-100">{data.reports.length} to review</span></div><div class="mt-4 space-y-3">{#each data.reports as report (report.id)}<article class="report-card rounded-2xl border border-white/[0.07] bg-black/10 p-4"><div class="flex flex-wrap items-center justify-between gap-2"><div class="flex items-center gap-2"><span class="report-reason">{report.reason}</span><span class="text-[10px] text-slate-600">{report.targetType} report</span></div><span class="text-[10px] text-slate-600">{niceDate(report.createdAt)}</span></div><h3 class="mt-3 text-sm font-bold text-slate-100">{report.postTitle || `Target ${report.targetId}`}</h3><p class="mt-1 text-xs text-slate-500">Reported by @{report.reporter}</p>{#if report.details}<p class="mt-3 rounded-xl bg-white/[0.025] p-3 text-xs leading-5 text-slate-400">{report.details}</p>{/if}<div class="mt-4 flex flex-wrap gap-2"><button onclick={() => action({ action: 'takeDownReport', targetId: report.id, reason: `Reported for ${report.reason}` }, 'Target removed. Report resolved.')} class="mini-danger">Remove content & resolve</button><button onclick={() => action({ action: 'resolveReport', targetId: report.id }, 'Report resolved.')} class="mini-button">Resolve — no removal</button><button onclick={() => action({ action: 'dismissReport', targetId: report.id }, 'Report dismissed.')} class="mini-button">Dismiss report</button></div></article>{:else}<div class="py-14 text-center"><div class="mx-auto flex h-12 w-12 items-center justify-center rounded-2xl bg-emerald-300/[0.06] text-xl text-emerald-200">✓</div><h3 class="mt-3 font-bold text-white">Queue clear</h3><p class="mt-1 text-xs text-slate-600">There are no reports waiting for review.</p></div>{/each}</div></section>

		{:else if activeSection === 'posts'}
			<section class="surface-card mt-5 rounded-[1.35rem] p-4 sm:p-5"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">CONTENT CONTROLS</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Recent posts</h2><p class="mt-1 text-xs text-slate-500">Pin high-value discussions, lock threads that need to cool down, or remove content that violates site rules.</p></div><div class="mt-4 space-y-2.5">{#each data.posts as post (post.id)}<div class="post-admin-row flex flex-col gap-3 rounded-xl border border-white/[0.055] bg-white/[0.012] p-3.5 sm:flex-row sm:items-center"><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><span class="rounded-md bg-indigo-300/[0.07] px-1.5 py-0.5 text-[9px] font-bold text-indigo-100">c/{post.community}</span>{#if post.isStickied}<span class="text-[9px] font-bold text-amber-200">Pinned</span>{/if}{#if post.isLocked}<span class="text-[9px] font-bold text-slate-500">Locked</span>{/if}{#if post.isRemoved}<span class="text-[9px] font-bold text-rose-200">Removed</span>{/if}</div><a href={`/post/${post.id}`} class="mt-2 block line-clamp-2 text-xs font-bold leading-5 text-slate-200 hover:text-white">{post.title}</a><p class="mt-1 text-[10px] text-slate-600">by @{post.author} · {compact(post.score)} score · {compact(post.commentCount)} replies · {niceDate(post.createdAt)}</p></div><div class="flex shrink-0 flex-wrap gap-1.5"><button onclick={() => action({ action: 'pinPost', targetId: post.id }, post.isStickied ? 'Post unpinned.' : 'Post pinned.')} class="mini-button">{post.isStickied ? 'Unpin' : 'Pin'}</button><button onclick={() => action({ action: 'lockPost', targetId: post.id }, post.isLocked ? 'Thread unlocked.' : 'Thread locked.')} class="mini-button">{post.isLocked ? 'Unlock' : 'Lock'}</button><button onclick={() => action({ action: post.isRemoved ? 'restorePost' : 'removePost', targetId: post.id, reason: 'Owner moderation decision' }, post.isRemoved ? 'Post restored.' : 'Post removed.')} class={post.isRemoved ? 'mini-button' : 'mini-danger'}>{post.isRemoved ? 'Restore' : 'Remove'}</button></div></div>{/each}</div></section>

		{:else if activeSection === 'verification'}
			<section class="surface-card mt-5 rounded-[1.35rem] p-4 sm:p-5"><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">AUTHENTICITY REVIEW</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Verification requests</h2><p class="mt-1 text-xs leading-5 text-slate-500">Review requests manually. A badge indicates an account was reviewed; it is not a paid endorsement and does not grant moderator permissions. Avoid requesting unnecessary identity documents.</p><div class="mt-4 space-y-3">{#each data.verificationRequests as request (request.id)}<article class="rounded-xl border border-white/[0.07] bg-black/10 p-4"><div class="flex flex-wrap items-start justify-between gap-2"><div><p class="text-sm font-bold text-slate-100">{request.displayName} <span class="text-xs font-medium text-slate-500">@{request.username}</span></p><p class="mt-1 text-[10px] text-slate-600">Submitted {niceDate(request.createdAt)}</p></div><span class="role-pill">Pending</span></div><p class="mt-3 whitespace-pre-wrap text-xs leading-5 text-slate-300">{request.reason}</p>{#if request.evidenceUrl}<a href={request.evidenceUrl} target="_blank" rel="noopener noreferrer" class="mt-3 inline-flex text-xs font-semibold text-sky-200 hover:text-white">Open supporting link ↗</a>{/if}<div class="mt-4 flex flex-wrap gap-2"><button onclick={() => action({ action: 'approveVerificationRequest', targetId: request.id, reason: 'Approved after owner review.' }, `@${request.username} is now verified.`)} class="mini-button mini-active" disabled={busy}>Approve and verify</button><button onclick={() => { const reviewerNote = window.prompt(`Reason for declining @${request.username}'s request:`, 'Not enough public evidence to establish authenticity.'); if (reviewerNote?.trim()) action({ action: 'rejectVerificationRequest', targetId: request.id, reviewNote: reviewerNote, reason: reviewerNote }, 'Verification request declined.'); }} class="mini-danger" disabled={busy}>Decline…</button></div></article>{:else}<p class="rounded-xl border border-white/[0.05] p-8 text-center text-xs text-slate-600">No verification requests are waiting for review.</p>{/each}</div></section>
		{:else if activeSection === 'users'}
			<section class="surface-card mt-5 rounded-[1.35rem] p-4 sm:p-5"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">MEMBER MANAGEMENT</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Users, roles, and account health</h2><p class="mt-1 text-xs leading-5 text-slate-500">Grant admin or moderator capabilities only to trusted members. Owner accounts are protected from these actions.</p></div><div class="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-300/10 bg-amber-300/[0.035] p-3"><div><p class="text-xs font-bold text-amber-100">Recalculate legacy karma</p><p class="mt-1 max-w-xl text-[10px] leading-4 text-slate-500">Rebuilds post and comment karma from current votes after schema migration. Existing moderator roles and verified status are not affected.</p></div><button onclick={() => { if (window.confirm('Recalculate karma for all users from current non-removed posts and comments?')) action({ action: 'rebuildKarma', reason: 'Owner requested one-time karma reconciliation.' }, 'Karma totals rebuilt from current votes.'); }} disabled={busy} class="mini-button">Recalculate karma</button></div><div class="mt-4 overflow-x-auto"><table class="admin-table"><thead><tr><th>Member</th><th>Role</th><th>Total karma</th><th>Post / comment</th><th>Joined</th><th>Status</th><th>Actions</th></tr></thead><tbody>{#each data.users as user (user.id)}<tr><td><div class="text-xs font-bold text-slate-200">{user.displayName}{#if user.isOwner}<span class="ml-1 text-violet-200">✦</span>{/if}{#if user.isVerified}<span class="ml-1 text-sky-200">✓</span>{/if}</div><div class="mt-1 text-[10px] text-slate-600">@{user.username} · {user.email}</div></td><td>{#if !user.isOwner && user.id !== data.viewer.id}<Dropdown label={`Role for @${user.username}`} value={user.role} options={roleOptions} onChange={(role) => changeRole(user.id, role)} />{:else}<span class="role-pill">{user.role}</span>{/if}</td><td>{compact(user.karma)}</td><td><span class="block text-[10px] text-slate-300">{compact(user.postKarma)} post</span><span class="mt-1 block text-[10px] text-slate-600">{compact(user.commentKarma)} comment</span></td><td>{new Date(user.createdAt).toLocaleDateString()}</td><td><span class={user.isBanned ? 'state-banned' : user.isShadowBanned ? 'state-banned' : 'state-active'}>{user.isBanned ? (user.banUntil && new Date(user.banUntil).getTime() > Date.now() ? 'Temp ban' : 'Suspended') : user.isShadowBanned ? 'Shadow-banned' : 'Active'}</span></td><td>{#if !user.isOwner && user.id !== data.viewer.id}<div class="flex flex-wrap gap-1"><button onclick={() => action({ action: 'verifyUser', targetId: user.id, verified: !user.isVerified }, user.isVerified ? 'Verification removed.' : 'Member verified.')} class="mini-button">{user.isVerified ? 'Unverify' : 'Verify'}</button><button onclick={() => banUser(user)} class={user.isBanned ? 'mini-button' : 'mini-danger'}>{user.isBanned ? 'Restore' : 'Ban'}</button><button onclick={() => tempBanUser(user)} class="mini-button">Temp ban</button><button onclick={() => toggleShadowBan(user)} class={user.isShadowBanned ? 'mini-button mini-active' : 'mini-button'}>{user.isShadowBanned ? 'Lift shadow' : 'Shadowban'}</button></div>{:else}<span class="text-[10px] text-slate-600">Protected</span>{/if}</td></tr>{/each}</tbody></table></div><p class="mt-3 text-[10px] text-slate-600">Showing the most recent 15 accounts. User search and pagination can be added as the community grows.</p></section>

		{:else if activeSection === 'support'}
			<section class="surface-card mt-5 rounded-[1.35rem] p-4 sm:p-5"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">HELP DESK</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Open customer support tickets</h2><p class="mt-1 text-xs text-slate-500">Support tickets may include personal information. View only what is needed, and never ask users to send passwords or encryption private keys.</p></div><div class="mt-4 space-y-3">{#each data.supportTickets as ticket (ticket.id)}<article class="rounded-xl border border-white/[0.06] bg-black/10 p-4"><div class="flex flex-wrap items-start justify-between gap-2"><div><span class="report-reason">{ticket.category}</span><h3 class="mt-2 text-sm font-bold text-slate-100">{ticket.subject}</h3><p class="mt-1 text-[10px] text-slate-600">@{ticket.username} · {ticket.email || 'No contact email'} · {niceDate(ticket.createdAt)}</p></div></div><p class="mt-3 whitespace-pre-wrap text-xs leading-5 text-slate-400">{ticket.message}</p><div class="mt-4 flex flex-wrap gap-2"><button onclick={() => action({ action: 'resolveSupportTicket', targetId: ticket.id }, 'Support ticket resolved.')} class="mini-button">Resolve</button><button onclick={() => action({ action: 'closeSupportTicket', targetId: ticket.id }, 'Support ticket closed.')} class="mini-button">Close</button></div></article>{:else}<p class="rounded-xl border border-white/[0.05] p-8 text-center text-xs text-slate-600">No open support tickets.</p>{/each}</div></section>
		{:else if activeSection === 'privacy'}
			<section class="surface-card mt-5 rounded-[1.35rem] p-4 sm:p-5"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">DATA SUBJECT RIGHTS</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Privacy requests</h2><p class="mt-1 text-xs leading-5 text-slate-500">Verify requester identity appropriately before disclosure or erasure. Preserve records only where there is a documented lawful basis or legal retention need.</p></div><div class="mt-4 space-y-3">{#each data.privacyRequests as request (request.id)}<article class="rounded-xl border border-white/[0.06] bg-black/10 p-4"><div class="flex flex-wrap items-center justify-between gap-2"><span class="report-reason">{request.requestType}</span><span class="text-[10px] text-slate-600">@{request.username} · {niceDate(request.createdAt)}</span></div>{#if request.details}<p class="mt-3 text-xs leading-5 text-slate-400">{request.details}</p>{/if}<div class="mt-4 flex flex-wrap gap-2"><button onclick={() => { const resolutionNote = window.prompt('Describe how this request was handled (do not put unnecessary personal data here):', 'Identity verified; requested action completed.'); if (resolutionNote?.trim()) action({ action: 'resolvePrivacyRequest', targetId: request.id, resolutionNote }, 'Privacy request marked resolved.'); }} class="mini-button">Mark handled</button><button onclick={() => { const resolutionNote = window.prompt('Explain why the request cannot be fulfilled or needs clarification:', 'Further identity verification or legal review is required.'); if (resolutionNote?.trim()) action({ action: 'rejectPrivacyRequest', targetId: request.id, resolutionNote }, 'Privacy request updated.'); }} class="mini-button">Needs review / reject</button></div></article>{:else}<p class="rounded-xl border border-white/[0.05] p-8 text-center text-xs text-slate-600">No new privacy requests.</p>{/each}</div></section>
		{:else if activeSection === 'communities'}
			<section class="surface-card mt-5 rounded-[1.35rem] p-4 sm:p-5"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">COMMUNITY GOVERNANCE</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Feature and restrict communities</h2></div><div class="mt-4 grid gap-3 sm:grid-cols-2">{#each data.communities as community (community.id)}<div class="rounded-xl border border-white/[0.06] bg-black/10 p-4"><div class="flex items-start justify-between gap-3"><div><p class="text-sm font-bold text-white">c/{community.slug}</p><p class="mt-1 text-[10px] text-slate-600">{community.name} · {compact(community.memberCount)} members</p><p class="mt-2 text-[10px] text-slate-500">{community.category} · {community.isPrivate ? 'Private' : 'Public'}</p></div>{#if community.isFeatured}<span class="text-xs text-amber-200">★</span>{/if}</div><div class="mt-4 flex flex-wrap gap-2"><button onclick={() => action({ action: 'featureCommunity', targetId: community.id }, community.isFeatured ? 'Community removed from featured.' : 'Community featured.')} class="mini-button">{community.isFeatured ? 'Unfeature' : 'Feature'}</button><button onclick={() => action({ action: 'togglePrivateCommunity', targetId: community.id }, community.isPrivate ? 'Community set to public.' : 'Community set to private.')} class="mini-button">{community.isPrivate ? 'Make public' : 'Restrict access'}</button><a href={`/c/${community.slug}`} class="mini-button inline-flex items-center">Open ↗</a></div></div>{/each}</div></section>

		{:else if activeSection === 'settings'}
			<form onsubmit={(event) => { event.preventDefault(); saveSettings(); }} class="surface-card mt-5 rounded-[1.35rem] p-5 sm:p-6"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">GLOBAL CONTROLS</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Site settings</h2><p class="mt-1 text-xs leading-5 text-slate-500">Changes here affect all site visitors and members.</p></div><div class="mt-5 grid gap-4"><label class="setting-label">Site tagline<input value={tagline} oninput={(event) => tagline = (event.currentTarget as HTMLInputElement).value} maxlength="200" class="admin-input"/></label><label class="setting-label">Default ranking<Dropdown label="Default ranking" value={defaultSort} options={adminSortOptions} onChange={(value) => defaultSort = value} fullWidth /></label><label class="setting-label">Post rate limit per hour<input bind:value={postRateLimitPerHour} type="number" min="1" max="100" class="admin-input"/><span class="text-[10px] font-normal text-slate-600">Regular members can publish this many posts per hour. Owner/admins bypass the limit.</span></label><div class="setting-switch"><span><b>Allow new registrations</b><small>New members can sign up for accounts.</small></span><input type="checkbox" bind:checked={allowRegistration} class="admin-check"/></div><div class="setting-switch"><span><b>Invite-only registration</b><small>Reserve new registrations for people with an invite.</small></span><input type="checkbox" bind:checked={inviteOnly} class="admin-check"/></div><div class="setting-switch"><span><b>Enable sensitive content</b><small>Allow users to opt in to posts marked 18+.</small></span><input type="checkbox" bind:checked={enableNsfw} class="admin-check"/></div><div class="setting-switch"><span><b>Realtime feed flag</b><small>Keep the app's realtime-feed capability enabled.</small></span><input type="checkbox" bind:checked={enableRealtimeFeed} class="admin-check"/></div></div><div class="mt-5 flex justify-end"><button type="submit" disabled={busy} class="rounded-xl bg-indigo-300 px-5 py-3 text-xs font-extrabold text-slate-950 disabled:opacity-50">{busy ? 'Saving…' : 'Save site settings ↗'}</button></div></form>

		{:else if activeSection === 'logs'}
			<section class="surface-card mt-5 rounded-[1.35rem] p-4 sm:p-5"><div><p class="text-[10px] font-bold uppercase tracking-[.16em] text-slate-600">ACCOUNTABILITY</p><h2 class="mt-1.5 text-lg font-extrabold text-white">Moderation audit log</h2><p class="mt-1 text-xs text-slate-500">A timestamped record of owner moderation and configuration actions.</p></div><div class="mt-4 overflow-x-auto"><table class="admin-table"><thead><tr><th>Action</th><th>Target</th><th>Actor</th><th>Reason</th><th>Time</th></tr></thead><tbody>{#each data.logs as log (log.id)}<tr><td><span class="role-pill">{log.action}</span></td><td><span class="text-xs text-slate-300">{log.targetType}</span><span class="mt-1 block text-[10px] text-slate-600">{log.targetId.slice(0, 18)}</span></td><td>@{log.actor}</td><td>{log.reason || '—'}</td><td>{niceDate(log.createdAt)}</td></tr>{:else}<tr><td colspan="5" class="py-10 text-center text-xs text-slate-600">No actions recorded yet.</td></tr>{/each}</tbody></table></div></section>
		{/if}
	</section>
</div>

<style>
	.owner-sidebar { position:sticky; top:92px; align-self:start; }
	.owner-mark { display:flex; height:37px; width:37px; align-items:center; justify-content:center; border-radius:12px; background:linear-gradient(140deg,#b8bfff,#c8a8ff); color:#0c1020; font-size:18px; font-weight:900; }
	.owner-nav { display:flex; width:100%; align-items:center; gap:11px; border:1px solid transparent; border-radius:11px; padding:11px 12px; text-align:left; color:#8e99af; font-size:12px; font-weight:700; transition:.18s; }
	.owner-nav:hover { background:rgba(255,255,255,.035); color:#fff; }
	.owner-nav-active { border-color:rgba(165,173,255,.11); background:rgba(129,140,248,.11); color:#e6e8ff; }
	.owner-nav-icon { display:inline-flex; width:20px; justify-content:center; color:#a5b4fc; font-size:16px; }
	.owner-badge { margin-left:auto; min-width:20px; border-radius:999px; background:rgba(251,113,133,.12); padding:3px 6px; text-align:center; color:#fecdd3; font-size:9px; }
	.owner-status { display:inline-flex; align-items:center; gap:7px; border:1px solid rgba(102,217,165,.12); border-radius:999px; background:rgba(102,217,165,.045); padding:8px 11px; color:#9ae6cd; font-size:10px; font-weight:700; }
	.stat-card { transition:transform .18s,border-color .18s; } .stat-card:hover { transform:translateY(-2px); border-color:rgba(161,170,255,.18); }
	.stat-alert { border-color:rgba(251,113,133,.18); background:linear-gradient(145deg,rgba(251,113,133,.055),rgba(12,16,25,.96)); }
	.rank-n { display:inline-flex; height:28px; width:28px; flex-shrink:0; align-items:center; justify-content:center; border-radius:9px; background:rgba(129,140,248,.08); color:#b4bdff; font-size:10px; font-weight:800; }
	.admin-table { width:100%; min-width:600px; border-collapse:collapse; text-align:left; }
	.admin-table th { padding:11px 10px; border-bottom:1px solid rgba(255,255,255,.06); color:#566177; font-size:9px; font-weight:800; text-transform:uppercase; letter-spacing:.1em; }
	.admin-table td { padding:13px 10px; border-bottom:1px solid rgba(255,255,255,.045); color:#738098; font-size:10px; vertical-align:middle; }
	.admin-table tr:last-child td { border-bottom:0; }
	.role-pill { display:inline-flex; border:1px solid rgba(150,160,255,.12); border-radius:6px; background:rgba(129,140,248,.06); padding:4px 7px; color:#b6c0ff; font-size:9px; font-weight:700; text-transform:capitalize; }
	.state-active,.state-banned { display:inline-flex; border-radius:999px; padding:4px 7px; font-size:9px; font-weight:700; }
	.state-active { background:rgba(110,231,183,.07); color:#9ae6cd; } .state-banned { background:rgba(251,113,133,.08); color:#fda4af; }
	.mini-button,.mini-danger { display:inline-flex; align-items:center; justify-content:center; border:1px solid rgba(255,255,255,.08); border-radius:8px; padding:7px 9px; color:#9ba6ba; font-size:10px; font-weight:700; transition:.18s; }
	.mini-button:hover { background:rgba(255,255,255,.05); color:#fff; } .mini-active { color:#fcd34d; border-color:rgba(252,211,77,.16); }
	.mini-danger { border-color:rgba(251,113,133,.12); background:rgba(251,113,133,.04); color:#fda4af; } .mini-danger:hover { background:rgba(251,113,133,.12); color:#ffe4e6; }
	.report-reason { border-radius:7px; background:rgba(251,113,133,.08); padding:5px 8px; color:#fecdd3; font-size:9px; font-weight:800; text-transform:uppercase; letter-spacing:.06em; }
	.role-select,.admin-input { border:1px solid rgba(255,255,255,.08); border-radius:10px; background:#111725; padding:8px 10px; color:#dbe1ef; font-size:11px; outline:none; }
	.admin-input { width:100%; padding:11px 12px; font-size:13px; font-weight:400; }
	.admin-input:focus,.role-select:focus { border-color:rgba(156,167,255,.35); }
	.setting-label { display:grid; gap:8px; color:#a4aec2; font-size:11px; font-weight:700; }
	.setting-switch { display:flex; align-items:center; justify-content:space-between; gap:18px; border:1px solid rgba(255,255,255,.06); border-radius:12px; padding:13px; }
	.setting-switch b { display:block; color:#d9dfec; font-size:12px; }
	.setting-switch small { display:block; margin-top:4px; color:#68748b; font-size:10px; line-height:1.5; }
	.admin-check { height:19px; width:19px; flex-shrink:0; border-color:#46516a; background:#111725; color:#a5b4fc; }
	@media(max-width:1023px) { .owner-sidebar { position:static; } .owner-sidebar nav { grid-template-columns:repeat(2,minmax(0,1fr)); } }
</style>
